import{_ as d,o as e,c as a,ag as l}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"ZCode 中国版体验","description":"AI Agent 零基础教程","frontmatter":{"title":"ZCode 中国版体验","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/05-zcode.md","filePath":"guide/05-zcode.md","lastUpdated":null}'),i={name:"guide/05-zcode.md"};function r(o,t,h,n,c,s){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="zcode-中国版体验" tabindex="-1">ZCode 中国版体验 <a class="header-anchor" href="#zcode-中国版体验" aria-label="Permalink to &quot;ZCode 中国版体验&quot;">​</a></h1><blockquote><p>状态：正文完成；共同基准任务已实测（2026-08-12）</p><p>本机版本：3.7.6</p><p>最后本机核对：2026-08-12；订阅核验：2026-08-11</p></blockquote><h2 id="_1-一句话结论" tabindex="-1">1. 一句话结论 <a class="header-anchor" href="#_1-一句话结论" aria-label="Permalink to &quot;1. 一句话结论&quot;">​</a></h2><p><strong>变更透明性最强的产品</strong>：审查视图提供逐文件增删统计（+46、+37、+84 等），每一份输入/输出/验收文件的改动都可逐项核对，Git 与任务管理深度整合。代价是门槛：本轮为 BYOK 配置（OpenCode Go + DeepSeek V4 Flash + 最高推理），需要理解模型/API/推理强度概念，新手要先跨过配置门槛。</p><h2 id="_2-测试版本和地区" tabindex="-1">2. 测试版本和地区 <a class="header-anchor" href="#_2-测试版本和地区" aria-label="Permalink to &quot;2. 测试版本和地区&quot;">​</a></h2><ul><li>测试日期：2026-08-12（统一基准实测）；界面截图核验 2026-08-13</li><li>正式产品名称与测试入口：ZCode 中国版（窗口与产品名均显示 <code>ZCode</code>）</li><li>地区版本：中国版</li><li>具体产品线：分组任务 + 项目工作台（代码优先型 Agent）</li><li>账号区域与计费币种：中国区账号；官方套餐积分计费，BYOK 由外部供应商结算</li><li>当前账号状态：正常（测试时）</li><li>官方服务是否覆盖当前地区：中国区官方运营</li><li>注册、登录与支付前提：中国区账号 + 支付方式或 API Key</li><li>账号受限后的申诉与恢复入口：官方支持渠道（未触发）</li><li>桌面客户端版本：3.7.6</li><li>操作系统：Windows（本机安装于 <code>E:\\Program\\Zcode</code>）</li><li>官方下载来源：ZCode 中国区官方下载入口</li><li>入门分组：代码优先型 Agent（国内）</li><li>主要任务方向：代码项目 / 持续任务 / 自定义模型通道</li><li>开放与后台运行方式：混合（官方积分路径或 BYOK）</li><li>自主程度：中—高（变更前确认可人工把关）</li><li>建议基础：编程或系统配置经验（新手门槛较高）</li><li>使用方案：新手体验 / GLM Coding Plan / API Key（BYOK）</li><li>官方订阅名称、价格与周期：首次使用 5 天体验：每日 GLM-5.2 300 万 Token + GLM-5-Turbo 200 万 Token（合计 500 万 Token/天）；官方推荐 BigModel 账号 + GLM Coding Plan（积分制，5 小时额度和每周额度并存；Pro、Max 用量约为 Lite 的 6 倍、14 倍，具体价格以套餐页为准）</li><li>套餐内用量单位：Token（新手体验）/ 积分（Coding Plan）/ 外部 API 账单（BYOK）</li><li>用量重置时间与结转规则：5 小时与每周额度并存；详见套餐页</li><li>官方 API 是否另行计费：BYOK 按外部供应商计费（本页记录为成本未知）</li><li>是否支持 BYOK：支持——BigModel、兼容 Anthropic/OpenAI 协议的 API Key、自定义供应商及团队通道</li><li>免费额度及核验来源：首次使用 5 天、每日 500 万 Token（官方新手页）</li><li>新用户或学生福利：即上述 5 天体验（连续 5 天每日发放，非一次性）</li><li>最后核验日期：2026-08-11</li><li>测试者背景：作者</li></ul><h2 id="_3-下载、安装与首次启动" tabindex="-1">3. 下载、安装与首次启动 <a class="header-anchor" href="#_3-下载、安装与首次启动" aria-label="Permalink to &quot;3. 下载、安装与首次启动&quot;">​</a></h2><ul><li>下载和安装：中国区官方下载，安装顺利；</li><li>是否必须注册、登录或绑定其他服务：需要账号；<strong>运行任务前需选择模型渠道</strong>（本轮未观察到统一 Auto 模式，需连接 OpenCode Go 等 Provider 或 BigModel 套餐）；</li><li>首次权限提示：权限模式可配置；本轮为「变更前确认」，写入文件前弹确认；</li><li>主界面导航：左侧按分组和项目管理任务，顶部新建任务、搜索、自动化与技能；中央输入区可选择项目、权限模式、模型和推理强度，并展示闲时任务模板；底部终端入口；</li><li>新手从启动到完成第一个任务：新建任务 → 选择运行目录 → 配置模型渠道与推理强度 → 设置权限 → 粘贴提示词 → 发送 → 按「变更前确认」逐次批准写入；</li><li>是否有只能通过 CLI/TUI 才能完成的重要能力：未发现；桌面端完成全部操作。</li></ul><h2 id="_4-免费额度、订阅与计费" tabindex="-1">4. 免费额度、订阅与计费 <a class="header-anchor" href="#_4-免费额度、订阅与计费" aria-label="Permalink to &quot;4. 免费额度、订阅与计费&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>实际记录</th><th>官方来源</th><th>最后核验日期</th></tr></thead><tbody><tr><td>免费额度</td><td>首次 5 天：每日 500 万 Token（GLM-5.2 300 万 + GLM-5-Turbo 200 万）</td><td>ZCode 新手与权益</td><td>2026-08-11</td></tr><tr><td>官方订阅</td><td>GLM Coding Plan（积分制；5 小时与每周额度并存；Pro/Max 约为 Lite 6/14 倍）</td><td>ZCode 连接模型与套餐</td><td>2026-08-11</td></tr><tr><td>用量单位与重置规则</td><td>Token / 积分；双额度窗口</td><td>官方文档</td><td>2026-08-11</td></tr><tr><td>新用户或学生福利</td><td>首次 5 天体验（连续发放）</td><td>官方新手页</td><td>2026-08-11</td></tr><tr><td>API 或 BYOK</td><td>BigModel、Anthropic/OpenAI 兼容协议、自定义供应商、团队通道</td><td>官方文档</td><td>2026-08-11</td></tr></tbody></table><p><strong>实测补充</strong>：本轮使用 BYOK（OpenCode Go API / DeepSeek V4 Flash / 最高推理 / 变更前确认），自身托管 Credits 不适用于本配置；<strong>本轮成本未记录（API 账单），成本维度为「未知」</strong>。</p><h2 id="_5-核心能力" tabindex="-1">5. 核心能力 <a class="header-anchor" href="#_5-核心能力" aria-label="Permalink to &quot;5. 核心能力&quot;">​</a></h2><ul><li>能处理哪些材料：文档、代码、项目文件；统一基准任务中一次生成 6 份 Markdown；</li><li>能调用哪些工具：文件系统、任务对话、审查视图（逐文件增删统计）、Git 面板（本轮用到）；自动化、技能、终端入口可见；</li><li>代表性功能：任务汇报（交付说明 + 未解决问题清单）、审查视图（文件+路径+增删行数+内容预览）、权限模式配置（变更前确认）；</li><li>哪些能力实际验证过：共同基准任务完整链路；哪些只来自官方说明：自动化、闲时任务模板等。</li></ul><h2 id="_6-界面与工作方式" tabindex="-1">6. 界面与工作方式 <a class="header-anchor" href="#_6-界面与工作方式" aria-label="Permalink to &quot;6. 界面与工作方式&quot;">​</a></h2><ul><li>运行位置：官方中国版桌面应用（模型经外部 Provider）；</li><li>用户如何观察和控制执行过程：中间任务汇报区看交付说明，右侧 Git 面板看提交与仓库状态，审查视图核对每份文件的增删。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>观察记录</th><th>适用前提</th></tr></thead><tbody><tr><td>新手上手难度</td><td>较高：需理解 Provider/API/模型/推理强度/权限模式</td><td>有配置经验者</td></tr><tr><td>账号与地区可用性</td><td>中国区正常</td><td>—</td></tr><tr><td>图形界面清晰度</td><td>典型 IDE 布局（文件树 + 汇报 + Git 面板三区联动）</td><td>—</td></tr><tr><td>任务状态反馈</td><td>任务汇报 + 未解决问题清单</td><td>—</td></tr><tr><td>权限提示与确认</td><td>「变更前确认」：本轮权限确认与人工回复各 ≥1 次（精确次数未记录）</td><td>写入可控但增加操作成本</td></tr><tr><td>上下文处理</td><td>未发现读取 input 之外文件</td><td>—</td></tr><tr><td>过程可控性</td><td>写入需人工批准，控制感强</td><td>—</td></tr><tr><td>结果定位与验证</td><td>审查视图逐文件增删统计，可逐项核对</td><td>自检漏列第 7 个输入文件</td></tr><tr><td>生态与扩展</td><td>自动化、技能、终端入口</td><td>未逐一实测</td></tr></tbody></table><p>界面细节见 「界面讲解文档」(docs/11-interface-guides/05-zcode-cn.md)（两张截图：整体界面/任务汇报、审查视图）。</p><h2 id="_7-三类实测任务" tabindex="-1">7. 三类实测任务 <a class="header-anchor" href="#_7-三类实测任务" aria-label="Permalink to &quot;7. 三类实测任务&quot;">​</a></h2><h3 id="_7-1-共同基准任务-2026-08-12" tabindex="-1">7.1 共同基准任务（2026-08-12） <a class="header-anchor" href="#_7-1-共同基准任务-2026-08-12" aria-label="Permalink to &quot;7.1 共同基准任务（2026-08-12）&quot;">​</a></h3><h4 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h4><p>使用冻结的教程材料包（<code>input/</code> 7 份文件），整理 AI Agent 教程材料，生成六个指定交付文件并自检。</p><h4 id="完整输入" tabindex="-1">完整输入 <a class="header-anchor" href="#完整输入" aria-label="Permalink to &quot;完整输入&quot;">​</a></h4><p>冻结材料包 + <code>zcode-prompt.md</code> 统一提示。</p><h4 id="执行过程" tabindex="-1">执行过程 <a class="header-anchor" href="#执行过程" aria-label="Permalink to &quot;执行过程&quot;">​</a></h4><p>打开 ZCode → 新建任务并选择运行目录 → 不执行配置助手或初始化 → 保持默认权限、模型与推理（BYOK：OpenCode Go / DeepSeek V4 Flash / 最高）→ 粘贴统一提示发送；执行中按「变更前确认」批准写入并回复继续。</p><h4 id="最终结果" tabindex="-1">最终结果 <a class="header-anchor" href="#最终结果" aria-label="Permalink to &quot;最终结果&quot;">​</a></h4><p>六份指定文件按顺序生成（08:38:16 首文件至 08:40:42 末文件），总用时 5 分 41 秒（测试者记录；首末文件间隔 2 分 26 秒）。</p><h4 id="验收情况" tabindex="-1">验收情况 <a class="header-anchor" href="#验收情况" aria-label="Permalink to &quot;验收情况&quot;">​</a></h4><ul><li>交付：6/6 一次完成，无中断/报错/重试；7/7 输入 SHA-256 与基线一致；权限确认与人工回复各 ≥1 次（精确次数未记录）；</li><li>内容亮点：材料边界处理较好（明确声明目录是重建提案）；写作计划 P0-P2、依赖链、阻塞项完整；待办九组复选框分层清楚；未发现读取 input 之外文件；</li><li>内容偏差：自行生成第 0–11 部分目录（声明为需合并的提案）；<strong>自检漏列第 7 个输入文件 <code>OUTPUT-REQUIREMENTS.md</code></strong>，且未反映真实权限确认过程；</li><li>指标：澄清/人工回复 ≥1 次；权限确认 ≥1 次；中断 0 / 报错 0 / 重试 0 / 恢复 0。</li></ul><table tabindex="0"><thead><tr><th>指标</th><th>记录</th></tr></thead><tbody><tr><td>开始与完成时间</td><td>2026-08-12 08:38:16 — 08:40:42</td></tr><tr><td>总用时</td><td>5 分 41 秒</td></tr><tr><td>人工介入次数及原因</td><td>≥1（权限确认后继续；具体次数未记录）</td></tr><tr><td>权限确认次数</td><td>≥1（变更前确认模式）</td></tr><tr><td>生成或修改的交付文件</td><td>6/6 指定文件</td></tr><tr><td>是否一次通过验收</td><td>指定文件一次完成；按预设权限流程人工确认和回复</td></tr><tr><td>失败后的恢复路径</td><td>未触发</td></tr></tbody></table><h3 id="_7-2-优势任务" tabindex="-1">7.2 优势任务 <a class="header-anchor" href="#_7-2-优势任务" aria-label="Permalink to &quot;7.2 优势任务&quot;">​</a></h3><p>候选：代码项目修改、审查、验证与持续任务（代码优先型优势场景）。<strong>待 benchmark v2 统一测试</strong>。</p><h3 id="_7-3-边界任务" tabindex="-1">7.3 边界任务 <a class="header-anchor" href="#_7-3-边界任务" aria-label="Permalink to &quot;7.3 边界任务&quot;">​</a></h3><p>候选：外部 Provider 不可用、API 余额耗尽、权限拒绝时的恢复。<strong>本轮未触发恢复场景</strong>；BYOK 本身即为「边界前置」：速度、质量与成本都依赖外部供应商状态。</p><h2 id="_8-遇到的问题与恢复" tabindex="-1">8. 遇到的问题与恢复 <a class="header-anchor" href="#_8-遇到的问题与恢复" aria-label="Permalink to &quot;8. 遇到的问题与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>出现条件</th><th>对结果的影响</th><th>恢复步骤</th><th>新手能否独立处理</th></tr></thead><tbody><tr><td>默认任务需自行选择模型渠道</td><td>3.7.6 未观察到统一 Auto 模式</td><td>新手需理解 API/模型/推理强度；结果与成本受供应商影响</td><td>明确记录 BYOK 组合，不与默认 Auto 混评</td><td>无基础的新手可能需要额外指导</td></tr><tr><td>写入文件需确认并人工回复</td><td>权限为「变更前确认」</td><td>增加端到端用时与操作次数，但提高写入可控性</td><td>测试者确认后继续</td><td>确认文案是否易懂待截图评价</td></tr><tr><td>自检不完整</td><td>漏列第 7 个输入文件、未反映权限确认</td><td>只看自检会低估实际介入</td><td>以人工验收与运行记录为准</td><td>需要教程示范独立核验</td></tr></tbody></table><p>本轮未出现执行错误或中断。</p><h2 id="_9-适合与不适合" tabindex="-1">9. 适合与不适合 <a class="header-anchor" href="#_9-适合与不适合" aria-label="Permalink to &quot;9. 适合与不适合&quot;">​</a></h2><h3 id="更适合" tabindex="-1">更适合 <a class="header-anchor" href="#更适合" aria-label="Permalink to &quot;更适合&quot;">​</a></h3><ul><li>需要 Git 级变更透明的代码用户（逐文件增删统计可逐项核对）；</li><li>愿意配置模型与 API、重视写入可控性（变更前确认）的用户；</li><li>有编程或系统配置经验的用户。</li></ul><h3 id="可能不适合" tabindex="-1">可能不适合 <a class="header-anchor" href="#可能不适合" aria-label="Permalink to &quot;可能不适合&quot;">​</a></h3><ul><li>零基础新手（模型/API/推理概念门槛高）；</li><li>想要「打开就用」托管体验的用户（无统一 Auto 模式）；</li><li>希望客户端内直接看到成本费用的用户（BYOK 成本需另查供应商账单）。</li></ul><h2 id="_10-最终结论" tabindex="-1">10. 最终结论 <a class="header-anchor" href="#_10-最终结论" aria-label="Permalink to &quot;10. 最终结论&quot;">​</a></h2><ul><li>是否推荐新手试用：<strong>有条件推荐</strong>——有配置基础者可先体验 5 天新手额度；纯零基础建议先看教程第 2 章「模型/API」概念再试；</li><li>什么条件下值得购买官方订阅：代码任务量大且需要完整变更审阅时，GLM Coding Plan 按档位选择；BYOK 用户按供应商用量评估；</li><li>最适合作为主 Agent、辅助 Agent 还是专用工具：<strong>代码/项目型主 Agent 候选</strong>（变更透明性最高）；</li><li>与相邻产品的差异：与 Qoder 同属代码优先型，ZCode 是 BYOK 路径（变更统计最细、写入需批准），Qoder 是托管 Auto 路径（最快最省但边界失分）；与 Codex 相比，ZCode 变更统计更细但配置门槛更高，Codex 托管订阅开箱即用；</li><li>仍需要后续版本继续核验：统一 Auto 模式是否提供、精确权限确认次数、代码优势任务、外部成本核算。</li></ul><h2 id="附录-a-截图清单" tabindex="-1">附录 A：截图清单 <a class="header-anchor" href="#附录-a-截图清单" aria-label="Permalink to &quot;附录 A：截图清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>截图</th><th>用途</th><th>日期或版本</th><th>是否脱敏</th><th>替代文字</th></tr></thead><tbody><tr><td>整体界面.png</td><td>任务汇报与 IDE 布局</td><td>3.7.6</td><td>是</td><td>任务汇报与文件树</td></tr><tr><td>审查详情.png</td><td>逐文件增删统计</td><td>同上</td><td>是</td><td>审查视图变更清单</td></tr></tbody></table><h2 id="附录-b-信息来源" tabindex="-1">附录 B：信息来源 <a class="header-anchor" href="#附录-b-信息来源" aria-label="Permalink to &quot;附录 B：信息来源&quot;">​</a></h2><ul><li><a href="https://zcode.z.ai/cn/docs/welcome" target="_blank" rel="noreferrer">ZCode 新手与权益</a>、<a href="https://zcode.z.ai/cn/docs/configuration" target="_blank" rel="noreferrer">ZCode 连接模型与套餐</a>（访问日期 2026-08-11）</li><li>运行记录：<code>research/runs/2026-08-12-zcode-cn-v3.7.6/run-record.md</code></li><li>界面讲解：<code>docs/11-interface-guides/05-zcode-cn.md</code></li></ul><h2 id="附录-c-内容性质标记" tabindex="-1">附录 C：内容性质标记 <a class="header-anchor" href="#附录-c-内容性质标记" aria-label="Permalink to &quot;附录 C：内容性质标记&quot;">​</a></h2><p>本文区分：官方事实（新手额度、套餐结构）、实际测试（共同基准任务）、作者观察（界面与门槛）、待验证（Auto 模式、精确介入次数）。5 分 41 秒是 ZCode + OpenCode Go + DeepSeek V4 Flash + 最高推理 + 变更前确认共同作用的结果，不能单独归因于 ZCode 或 DeepSeek；BYOK 成本未知，不与托管 Credits 比较。</p>',50)])])}const p=d(i,[["render",r]]);export{b as __pageData,p as default};
